<?php require 'includes/database.php';$c=$_GET['c']??'';$st=$pdo->prepare("SELECT s.*,COALESCE(AVG(r.rating),0) avg_rating FROM shops s LEFT JOIN reviews r ON r.shop_id=s.id WHERE s.category=? GROUP BY s.id ORDER BY avg_rating DESC");$st->execute([$c]);$shops=$st->fetchAll();require 'includes/header.php';?><main class="wrap"><h2><?=htmlspecialchars($c)?></h2><div class="grid"><?php foreach($shops as $s):?><a class="card" href="shop.php?id=<?=$s['id']?>"><img class="shop-img" src="<?=htmlspecialchars($s['image']?:'https://placehold.co/600x360')?>"><h3><?=htmlspecialchars($s['name'])?></h3><p class="stars">★ <?=number_format($s['avg_rating'],1)?></p></a><?php endforeach;?></div></main><?php require 'includes/footer.php';?>
